
const KEY='netflow_reseller_billing_v14';
// Robust local storage bootstrap: a malformed/stale localStorage record must never blank the app.
function safeLoadDb(){
  try{
    const raw=localStorage.getItem(KEY);
    if(!raw) return null;
    const parsed=JSON.parse(raw);
    return parsed && typeof parsed==='object' ? parsed : null;
  }catch(err){
    console.warn('Ignoring invalid local NetFlow data:',err);
    try{localStorage.removeItem(KEY)}catch(e){}
    return null;
  }
}
