let supabaseClient=null, cloudUser=null, cloudBusy=false, cloudReady=false, cloudChannel=null; let profile=null; let workspaceId=null;
function getSupabase(){
  const url=localStorage.getItem(SUPABASE_URL_KEY)||DEFAULT_SUPABASE_URL;
  const key=localStorage.getItem(SUPABASE_ANON_KEY)||DEFAULT_SUPABASE_KEY;
  if(!url||!key||!window.supabase) return null;
  try{
    return window.supabase.createClient(url,key,{
      auth:{autoRefreshToken:true,persistSession:true,detectSessionInUrl:true}
    });
  }catch(e){console.error('Supabase client creation failed',e);return null}
}
async function testCloudConnection(url,key){
  url=(url||'').trim().replace(/\/$/,''); key=(key||'').trim();
  if(!/^https:\/\/[^\s]+\.supabase\.co$/i.test(url)) throw new Error('Project URL looks invalid. Use https://YOUR_PROJECT.supabase.co');
  if(!key) throw new Error('Enter the Supabase publishable/anon public key.');
  const controller=new AbortController(); const timer=setTimeout(()=>controller.abort(),10000);
  try{
    const r=await fetch(url+'/auth/v1/settings',{method:'GET',headers:{apikey:key},signal:controller.signal,cache:'no-store'});
    const text=await r.text();
    if(!r.ok) throw new Error('Supabase responded HTTP '+r.status+(text?' — '+text.slice(0,180):''));
    return true;
  }catch(e){
    if(e?.name==='AbortError') throw new Error('Supabase connection timed out. Check the Project URL, internet/VPN, or an iPhone content blocker.');
    if(/Failed to fetch|Load failed|NetworkError/i.test(String(e?.message||e))) throw new Error('The browser cannot reach Supabase. Check the Project URL, internet/VPN, DNS, or Safari content blockers.');
    throw e;
  }finally{clearTimeout(timer)}
}
