function restoreBackup(file){const r=new FileReader();r.onload=e=>{try{const x=JSON.parse(e.target.result);if(!x.data||!x.data.customers)throw new Error('Invalid NetFlow backup');db=Object.assign(emptyDb(),x.data);localStorage.setItem(KEY,JSON.stringify(db));logAction('Backup restored','Restored backup from '+(x.createdAt||'unknown date'));render();toast('Backup restored')}catch(err){alert('Restore failed: '+err.message)}};r.readAsText(file)}
function maybeAutoBackup(){const bs=db.backupSettings||{};if(!bs.enabled)return;const last=bs.lastBackup?new Date(bs.lastBackup).getTime():0;if(Date.now()-last >= Number(bs.intervalHours||24)*3600000){const snapshot={version:1,createdAt:new Date().toISOString(),app:'NetFlow ISP',data:db};localStorage.setItem('netflow_auto_backup',JSON.stringify(snapshot));db.backupSettings.lastBackup=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(db));}}
function paymentTokenEncode(obj){const raw=JSON.stringify(obj);return btoa(unescape(encodeURIComponent(raw))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function paymentTokenDecode(token){try{const b64=String(token||'').replace(/-/g,'+').replace(/_/g,'/');return JSON.parse(decodeURIComponent(escape(atob(b64))))}catch(e){return null}}
function makePaymentLink(invoice){const c=db.customers.find(x=>x.id===invoice.customerId);const ps=db.paymentSettings||{},payload={invoiceId:invoice.id,no:invoice.no,name:c?.name||'',phone:c?.phone||'',amount:Math.max(0,Number(invoice.retail||0)-Number(invoice.paid||0)),dueDate:invoice.dueDate||'',currency:ps.currency||'PKR',easypaisaUrl:ps.easypaisa?.enabled?ps.easypaisa?.checkoutUrl||'':'',jazzcashUrl:ps.jazzcash?.enabled?ps.jazzcash?.checkoutUrl||'':'',createdAt:Date.now()};const token=paymentTokenEncode(payload);db.paymentLinks=db.paymentLinks.filter(x=>x.invoiceId!==invoice.id);db.paymentLinks.push({token,invoiceId:invoice.id,createdAt:new Date().toISOString(),status:'active'});localStorage.setItem(KEY,JSON.stringify(db));return location.origin+location.pathname+'?pay='+token}
function openPaymentLink(invoice){const url=makePaymentLink(invoice);window.open(url,'_blank','noopener,noreferrer');return url}
function sendPaymentWhatsApp(invoice){const c=db.customers.find(x=>x.id===invoice.customerId);if(!c?.phone)return alert('Customer phone number is missing.');const outstanding=Math.max(0,Number(invoice.retail||0)-Number(invoice.paid||0));if(outstanding<=0)return alert('This invoice is already paid.');const url=makePaymentLink(invoice);let n=String(c.phone).replace(/\D/g,'');if(n.startsWith('0'))n='92'+n.slice(1);const msg=`Assalam-o-Alaikum ${c.name},\n\nYour internet bill ${invoice.no} is due.\nAmount: ${money(outstanding)}\nDue date: ${invoice.dueDate||'—'}\n\n💳 Pay online:\n${url}\n\nThank you.`;window.open('https://wa.me/'+n+'?text='+encodeURIComponent(msg),'_blank','noopener,noreferrer');logAction('Payment reminder sent','WhatsApp payment link for '+invoice.no);return url}
function gatewayUrlFor(invoice){const s=db.paymentSettings||{};if(!s.checkoutUrl)return '';const c=db.customers.find(x=>x.id===invoice.customerId);const amount=Math.max(0,Number(invoice.retail||0)-Number(invoice.paid||0));return String(s.checkoutUrl).replaceAll('{{invoice_id}}',encodeURIComponent(invoice.id)).replaceAll('{{invoice_no}}',encodeURIComponent(invoice.no)).replaceAll('{{amount}}',encodeURIComponent(amount)).replaceAll('{{currency}}',encodeURIComponent(s.currency||'PKR')).replaceAll('{{customer_name}}',encodeURIComponent(c?.name||'' )).replaceAll('{{return_url}}',encodeURIComponent(location.origin+location.pathname+'?payment_return=1'))}
function gatewayUrlForProvider(invoice,provider){const ps=db.paymentSettings||{};const cfg=provider==='easypaisa'?(ps.easypaisa||{}):(ps.jazzcash||{});if(!cfg.enabled||!cfg.checkoutUrl)return '';const c=db.customers.find(x=>x.id===invoice.customerId);const amount=Math.max(0,Number(invoice.retail||0)-Number(invoice.paid||0));return String(cfg.checkoutUrl).replaceAll('{{invoice_id}}',encodeURIComponent(invoice.id)).replaceAll('{{invoice_no}}',encodeURIComponent(invoice.no)).replaceAll('{{amount}}',encodeURIComponent(amount)).replaceAll('{{currency}}',encodeURIComponent(ps.currency||'PKR')).replaceAll('{{customer_name}}',encodeURIComponent(c?.name||'')).replaceAll('{{customer_phone}}',encodeURIComponent(c?.phone||'')).replaceAll('{{return_url}}',encodeURIComponent(location.origin+location.pathname+'?payment_return=1'));}
function tokenGatewayUrl(x,provider){const u=provider==='easypaisa'?x?.easypaisaUrl:x?.jazzcashUrl;if(!u)return '';return String(u).replaceAll('{{invoice_id}}',encodeURIComponent(x.invoiceId)).replaceAll('{{invoice_no}}',encodeURIComponent(x.no)).replaceAll('{{amount}}',encodeURIComponent(x.amount)).replaceAll('{{currency}}',encodeURIComponent(x.currency||'PKR')).replaceAll('{{customer_name}}',encodeURIComponent(x.name||'')).replaceAll('{{customer_phone}}',encodeURIComponent(x.phone||'')).replaceAll('{{return_url}}',encodeURIComponent(location.origin+location.pathname+'?payment_return=1'));}
function markInvoicePaid(invoiceId,amount,method='Online Payment',reference=''){const i=db.invoices.find(x=>x.id===invoiceId);if(!i)throw new Error('Invoice not found');const outstanding=Math.max(0,Number(i.retail||0)-Number(i.paid||0));const n=Math.min(Number(amount||outstanding),outstanding);if(n<=0)return false;i.paid=Number(i.paid||0)+n;db.payments.push({id:uid(),invoiceId:i.id,customerId:i.customerId,amount:n,date:today(),method,note:'Online payment'+(reference?' • '+reference:'')});logAction('Online payment confirmed',i.no+' — '+money(n));save();return true}
function publicPaymentPage(){const token=new URLSearchParams(location.search).get('pay');const x=paymentTokenDecode(token);if(!x)return `<div class="page"><div class="card"><h1>Payment Link Invalid</h1><p class="subtle">This payment link is invalid or incomplete.</p></div></div>`;const i=db.invoices.find(v=>v.id===x.invoiceId);const amount=i?Math.max(0,Number(i.retail||0)-Number(i.paid||0)):Number(x.amount||0);const no=i?.no||x.no;const name=db.customers.find(c=>c.id===i?.customerId)?.name||x.name||'Customer';if(i&&amount<=0)return `<div class="page" style="max-width:720px"><div class="card" style="text-align:center;padding:40px"><div style="font-size:52px">✅</div><h1>Payment Already Complete</h1><p>${esc(no)} has no outstanding balance.</p><button class="btn primary" onclick="location.href=location.pathname">Open ISP System</button></div></div>`;const gateway=gatewayUrlFor(i||{id:x.invoiceId,no,retail:amount,paid:0,customerId:null});return `<div class="page" style="max-width:760px"><div class="card" style="padding:32px"><div class="logo" style="margin-bottom:16px">NF</div><h1>Internet Bill Payment</h1><p class="subtle">Secure payment request from NetFlow ISP.</p><div class="bill-row"><span>Customer</span><b>${esc(name)}</b></div><div class="bill-row"><span>Invoice</span><b>${esc(no)}</b></div><div class="bill-row"><span>Due date</span><b>${esc(i?.dueDate||x.dueDate||'—')}</b></div><div class="bill-row"><span>Amount</span><b class="green" style="font-size:24px">${money(amount)}</b></div><div class="notice" style="margin:18px 0">${gateway?'You will be redirected to the configured payment gateway. After successful payment, your invoice will be marked paid through the gateway webhook.':'Payment gateway is not configured yet. Use Demo Payment for testing, or configure a merchant checkout URL in API Integrations.'}</div><div class="notice" style="margin:18px 0"><b>EasyPaisa Manual Payment</b><br>Send payment to <b>03240616159</b> and keep your transaction ID. Then contact support to confirm the payment.</div><div class="actions">${((db.paymentSettings?.easypaisa?.enabled&&db.paymentSettings?.easypaisa?.checkoutUrl)||x?.easypaisaUrl)?'<button class="btn success" id="publicEasyPay">💚 Pay with EasyPaisa</button>':''}${((db.paymentSettings?.jazzcash?.enabled&&db.paymentSettings?.jazzcash?.checkoutUrl)||x?.jazzcashUrl)?'<button class="btn primary" id="publicJazzPay">💳 Pay with JazzCash</button>':''}<button class="btn" id="publicPayNow">Pay Online</button><button class="btn" id="publicDemoPay">✓ Demo Payment</button></div><p class="subtle" style="margin-top:14px;font-size:11px">Demo Payment is only for testing. It is not a real money transaction.</p></div></div>`}

