function emptyDb(){return {companies:[],packages:[],customers:[],invoices:[],payments:[],expenses:[],staff:[],devices:[],auditLogs:[],paymentLinks:[],paymentSettings:{enabled:true,checkoutUrl:'',currency:'PKR',provider:'Custom Gateway',webhookUrl:'/api/payments/webhook',easypaisa:{enabled:false,merchantId:'',password:'',storeId:'',checkoutUrl:'',webhookUrl:'',receiveNumber:'03240616159'},jazzcash:{enabled:false,merchantId:'',password:'',integritySalt:'',checkoutUrl:'',webhookUrl:''},whatsapp:{enabled:false,apiUrl:'https://graph.facebook.com/v23.0',phoneId:'',template:'isp_bill_reminder',language:'en'},massWhatsApp:{enabled:false,lastRun:null}},backupSettings:{enabled:true,intervalHours:24,lastBackup:null},apiIntegrations:[]}}
function mergeCloudDb(localData,remoteData){
  const out=emptyDb();
  Object.keys(out).forEach(k=>{
    const local=Array.isArray(localData?.[k])?localData[k]:[];
    const remote=Array.isArray(remoteData?.[k])?remoteData[k]:[];
    const map=new Map();
    remote.forEach(x=>map.set(String(x.id),x));
    local.forEach(x=>{if(x?.id && !map.has(String(x.id)))map.set(String(x.id),x);});
    out[k]=Array.from(map.values());
  });
  return out;
}
async function syncCloud(){
  if(!supabaseClient||!cloudUser||!cloudReady||cloudBusy||!workspaceId)return;
  cloudBusy=true;
  try{
    const {error}=await supabaseClient.from('isp_workspaces').upsert(
      {user_id:workspaceId,data:db,updated_at:new Date().toISOString()},
      {onConflict:'user_id'}
    );
    if(error)throw error;
  }catch(e){console.error(e);toast('Cloud sync failed: '+(e.message||'Check Supabase/RLS'));}finally{cloudBusy=false;}
}
function subscribeCloud(){
  if(!supabaseClient||!workspaceId)return;
  if(cloudChannel){supabaseClient.removeChannel(cloudChannel);cloudChannel=null;}
  cloudChannel=supabaseClient.channel('netflow-workspace-'+workspaceId)
    .on('postgres_changes',{event:'UPDATE',schema:'public',table:'isp_workspaces',filter:'user_id=eq.'+workspaceId},payload=>{
      if(!payload?.new?.data)return;
      db=Object.assign(emptyDb(),payload.new.data);
      localStorage.setItem(KEY,JSON.stringify(db));
      render();
    })
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'isp_workspaces',filter:'user_id=eq.'+workspaceId},payload=>{
      if(!payload?.new?.data)return;
      db=Object.assign(emptyDb(),payload.new.data);
      localStorage.setItem(KEY,JSON.stringify(db));
      render();
    })
    .subscribe();
}
async function loadCloud(){
  if(!supabaseClient||!cloudUser)return false;
  await getProfile();
  if(!profile||!workspaceId){cloudReady=false;render();return false}
  if(!PERMS[role()]){cloudReady=false;render();return false}
  const localBefore=JSON.parse(localStorage.getItem(KEY)||'null')||emptyDb();
  const {data,error}=await supabaseClient.from('isp_workspaces').select('data').eq('user_id',workspaceId).maybeSingle();
  if(error){console.error('Cloud workspace load failed',error);cloudReady=false;render();throw new Error('Cloud workspace load failed: '+error.message);}
  cloudReady=true;
  if(data?.data){
    db=mergeCloudDb(localBefore,data.data);
    localStorage.setItem(KEY,JSON.stringify(db));
    await syncCloud();
  }else if(canEditData()){
    await syncCloud();
  }
  subscribeCloud();
  render();
  return true;
}
async function authLogin(email,password){
  if(!supabaseClient) throw new Error('Supabase client is not available. Open Settings and test the Cloud connection.');
  email=String(email||'').trim(); password=String(password||'');
  if(!email||!password) throw new Error('Enter your full email address and password.');
  let lastErr=null;
  for(let attempt=1;attempt<=3;attempt++){
    try{
      const {data,error}=await supabaseClient.auth.signInWithPassword({email,password});
      if(error) throw error;
      if(!data?.user||!data?.session) throw new Error('Supabase did not return a login session.');
      cloudUser=data.user;
      const ok=await loadCloud();
      if(!ok) throw new Error('Login succeeded, but the ISP workspace could not be loaded. Run the included SQL in Supabase and check RLS policies.');
      toast('Login successful'); return;
    }catch(e){
      lastErr=e;
      const msg=String(e?.message||e);
      if(!/NetworkError|Failed to fetch|Load failed|fetch/i.test(msg)||attempt===3) break;
      await new Promise(r=>setTimeout(r,700*attempt));
    }
  }
  const msg=String(lastErr?.message||lastErr||'Unknown error');
  if(/NetworkError|Failed to fetch|Load failed|fetch/i.test(msg))
    throw new Error('Cannot reach Supabase. Check the Project URL, internet/VPN, DNS, Safari content blockers, and run Settings → Test Cloud Connection.');
  throw new Error(msg);
}
async function authSignup(email,password){
  if(!supabaseClient) throw new Error('Supabase client is not available. Open Settings and test the Cloud connection.');
  email=String(email||'').trim(); password=String(password||'');
  if(!email||!password) throw new Error('Enter your full email address and a password.');
  if(password.length<6) throw new Error('Password must be at least 6 characters.');
  const {data,error}=await supabaseClient.auth.signUp({email,password});
  if(error) throw error;
  if(data?.session&&data?.user){
    cloudUser=data.user;
    const ok=await loadCloud();
    if(!ok) throw new Error('Account was created, but the ISP workspace could not be loaded. Run the included SQL in Supabase and check RLS.');
    toast('Account created and logged in.');
  }else{
    cloudUser=null; profile=null; workspaceId=null; cloudReady=false; render();
    toast('Account created. Check your email to confirm the account, then login.');
  }
}
async function authLogout(){
  if(supabaseClient) await supabaseClient.auth.signOut();
  cloudUser=null; profile=null; workspaceId=null; cloudReady=false;
  if(cloudChannel){try{await supabaseClient.removeChannel(cloudChannel)}catch(e){} cloudChannel=null;}
  toast('Logged out'); render();
}
