async function claimInvite(token){if(!supabaseClient||!cloudUser)throw new Error('Login first');const {data,error}=await supabaseClient.rpc('claim_staff_invite',{p_token:token});if(error)throw error;await loadCloud();return data}

function toast(x){const t=document.getElementById('toast');t.textContent=x;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
const views=[['monitoring','◌','Monitoring Adapter'],['dashboard','⌂','Dashboard'],['companies','▦','Companies'],['customers','♙','Customers'],['packages','▣','Supplier Packages'],['billing','₨','Billing & Invoices'],['payments','✓','Payments'],['expenses','−','Expenses'],['staff','♟','Staff Management'],['reports','◉','Reports & Profit'],['import','⇧','Excel / CSV Import'],['devices','◉','Device Management'],['communications','☏','WhatsApp / SMS'],['integrations','⌘','API Integrations'],['backups','☁','Automatic Backups'],['audit','◈','Audit Logs'],['pingmonitor','◉','Ping Monitoring'],['oltadapter','◈','OLT Adapter'],['fiberMapping','⌁','Fiber Mapping'],['fiberCables','▤','Fiber Cables'],['fiberCores','◈','Fiber Cores'],['fiberJoints','⌘','Joint / Splice'],['fiberSplitters','◉','Splitters'],['fiberCalculation','∿','Fiber Calculation'],['fiberBudget','◫','Optical Power Budget'],['fiberFaults','⚠','Fiber Faults'],['fiberReports','▥','Fiber Reports'],['settings','⚙','Settings']];
const navGroups=[
  {id:'overview',icon:'⌂',label:'Overview',items:[['dashboard','Dashboard']]},
  {id:'customers',icon:'♙',label:'Customers & Suppliers',items:[['companies','Companies / Suppliers'],['customers','Customers'],['packages','Supplier Packages']]},
  {id:'billing',icon:'₨',label:'Billing & Finance',items:[['billing','Billing & Invoices'],['payments','Payments'],['expenses','Expenses'],['reports','Reports & Profit']]},
  {id:'network',icon:'◉',label:'Network',items:[['oltadapter','OLT Adapter'],['devices','OLT Dashboard'],['devices#overview','OLT Overview'],['devices#online','Online ONTs'],['devices#offline','Offline ONTs'],['devices#alarms','OLT Alarms'],['networkmonitor','Network Monitoring'],['mikrotik','MikroTik Dashboard'],['fiberMapping','Fiber Mapping'],['fiberCables','Fiber Cables'],['fiberCores','Fiber Cores'],['fiberJoints','Joint / Splice Management'],['fiberSplitters','Splitter Management'],['fiberCalculation','Fiber Calculation'],['fiberBudget','Optical Power Budget'],['fiberFaults','Fiber Faults'],['fiberReports','Fiber Reports']]},
  {id:'admin',icon:'⚙',label:'Administration',items:[['pingmonitor','Ping Monitoring'],['staff','Staff Management'],['import','Excel / CSV Import'],['settings','Settings'],['communications','WhatsApp / SMS'],['integrations','API Integrations'],['backups','Automatic Backups'],['audit','Audit Logs']]},
  {id:'monitoring',icon:'◌',label:'Monitoring Adapter',items:[['monitoring','Adapter Dashboard'],['monitoring#health','Adapter Health'],['monitoring#olt','OLT Connections'],['monitoring#logs','Monitoring Logs']]}
];
let openNavGroup=localStorage.getItem('netflow_open_nav_group')||'overview';
function nav(){
  const el=document.getElementById('nav');
  el.innerHTML=navGroups.map(g=>{
    const allowed=g.items.filter(i=>can(String(i[0]).split('#')[0]));
    if(!allowed.length)return '';
    const open=openNavGroup===g.id;
    return `<div class="nav-group ${open?'open':''}" data-nav-group="${g.id}"><button class="nav-main" type="button" data-nav-toggle="${g.id}"><span>${g.icon} &nbsp; ${g.label}</span><span class="nav-arrow">▶</span></button><div class="nav-sub">${allowed.map(i=>{const [target,label]=i;const [v,tab]=target.split('#');return `<button type="button" class="${view===v && (!tab || deviceTab===tab)?'active':''}" data-nav-item="${v}" ${tab?`data-nav-tab="${tab}"`:''} aria-label="Open ${label}">${label}</button>`}).join('')}</div></div>`;
  }).join('');
  el.querySelectorAll('[data-nav-toggle]').forEach(b=>b.onclick=(e)=>{e.preventDefault();e.stopPropagation();openNavGroup=b.dataset.navToggle;localStorage.setItem('netflow_open_nav_group',openNavGroup);nav()});
  el.querySelectorAll('[data-nav-item]').forEach(b=>b.addEventListener('click',(e)=>{e.preventDefault();e.stopPropagation();const target=String(b.dataset.navItem||'').trim();if(!target)return;if(!can(target)){toast('Access denied for this section');return;}view=target;const tab=b.dataset.navTab;if(tab){deviceTab=tab;localStorage.setItem('netflow_device_tab',deviceTab);selectedDeviceId=selectedDeviceId||db.devices?.[0]?.id||null;}if(target==='customers')customerFilterStatus='all';closeMobile();render();},{capture:true}));
}
function openView(target,tab){target=String(target||'').trim();if(!target||!can(target))return toast('Access denied for this section');view=target;if(tab){deviceTab=tab;localStorage.setItem('netflow_device_tab',deviceTab);}if(target==='customers')customerFilterStatus='all';closeMobile();render();}
function fillFilter(){const s=document.getElementById('companyFilter');s.innerHTML='<option value="all">All Companies</option>'+db.companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');s.value=filter;}
function companyName(id){return db.companies.find(c=>c.id===id)?.name||'—'}
function packageOf(id){return db.packages.find(p=>p.id===id)}
function customers(){return filter==='all'?db.customers:db.customers.filter(c=>c.companyId===filter)}
function packages(){return filter==='all'?db.packages:db.packages.filter(p=>p.companyId===filter)}
function invoices(){return filter==='all'?db.invoices:db.invoices.filter(i=>i.companyId===filter)}
function metrics(){const cs=customers(), ins=invoices(); const sales=cs.filter(c=>c.status!=='Suspended').reduce((a,c)=>a+Number(c.retail||packageOf(c.packageId)?.retail||0),0); const collected=ins.reduce((a,i)=>a+Number(i.paid||0),0); const supplier=cs.filter(c=>c.status!=='Suspended').reduce((a,c)=>a+Number(packageOf(c.packageId)?.cost||0),0); const exp=db.expenses.filter(e=>filter==='all'||e.companyId===filter).reduce((a,e)=>a+Number(e.amount||0),0); const staff=db.staff.filter(s=>s.active!==false&&(filter==='all'||s.companyId===filter)).reduce((a,s)=>a+Number(s.salary||0),0); const outstanding=Math.max(0,sales-collected); return{cs,sales,collected,supplier,commission:sales-supplier,expenses:exp+staff,net:sales-supplier-exp-staff,outstanding}}
function render(){if(new URLSearchParams(location.search).has('pay')){document.getElementById('content').innerHTML=publicPaymentPage();wirePublicPayment();return} if(!can(view))view=can('dashboard')?'dashboard':'settings';nav();fillFilter();document.getElementById('roleTop').textContent=role().toUpperCase();document.getElementById('userTop').textContent=cloudUser?.email||'Local';const el=document.getElementById('content');el.innerHTML=page(view);if(view==='pingmonitor'){try{wirePingMonitoring();}catch(e){console.error('Ping monitor wiring failed:',e);setTimeout(()=>wirePingMonitoring(),250);}}if(view==='oltadapter'){try{wireOltAdapter();}catch(e){console.error('OLT adapter wiring failed:',e);}}if(view==='networkmonitor'){try{wireNetworkMonitoring();}catch(e){console.error('Network monitor wiring failed:',e);setTimeout(()=>wireNetworkMonitoring(),250);}} if(['fiberMapping','fiberCables','fiberCores','fiberJoints','fiberSplitters','fiberCalculation','fiberBudget','fiberFaults','fiberReports'].includes(view)){loadFiberState().then(()=>{const c=document.getElementById('content');if(c)c.innerHTML=page(view);wireFiberModule();}).catch(()=>{});return;}try{wire();if(view==='settings')wirePingSettings();}catch(e){console.error('UI wiring error:',e);const c=document.getElementById('content');if(view!=='networkmonitor' && c){const n=document.createElement('div');n.className='notice section';n.innerHTML='<b class="red">Some controls could not be initialized.</b> The page itself is still available. Check the browser console for details.';c.prepend(n);}}startLiveBandwidthPolling();if(view==='dashboard'){requestAnimationFrame(renderCharts);requestAnimationFrame(()=>loadDashboardNetworkLive(false));}if(view==='customerDetail'&&viewCustomerId)requestAnimationFrame(()=>renderClientCharts(viewCustomerId)); if(view==='devices')requestAnimationFrame(renderSelectedOltBandwidth); if(view==='dashboard')requestAnimationFrame(loadPingDashboardSummary); if(view==='monitoring')requestAnimationFrame(loadMonitoringPage);}

function fiberApi(path,opts={}){return fetch(path,{...opts,headers:{'Content-Type':'application/json',...(opts.headers||{})}}).then(async r=>{const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.detail||j.error||('HTTP '+r.status));return j;});}
let fiberState={summary:null,cables:[],joints:[],splitters:[],routes:[],faults:[],calculations:[],settings:null};
async function loadFiberState(){try{const [summary,cables,joints,splitters,routes,faults,calculations,settings]=await Promise.all([fiberApi('/api/fiber/summary'),fiberApi('/api/fiber/cables'),fiberApi('/api/fiber/joints'),fiberApi('/api/fiber/splitters'),fiberApi('/api/fiber/routes'),fiberApi('/api/fiber/faults'),fiberApi('/api/fiber/calculations'),fiberApi('/api/fiber/settings')]);fiberState={summary:summary.summary||summary,cables:cables.cables||[],joints:joints.joints||[],_splices:joints.splices||[],splitters:splitters.splitters||[],routes:routes.routes||[],faults:faults.faults||[],calculations:calculations.calculations||[],settings:settings.settings||{}};return fiberState}catch(e){toast('Fiber backend: '+e.message);throw e}}
const fiberNodeTypes=['OLT','Fiber Cable','Joint / Splice','Splitter','Drop Fiber','ONU/ONT','Customer','MikroTik','Core Router','Switch'];
function fiberSummaryCards(){const x=fiberState.summary||{};return `<div class="grid fiber-kpi-grid"><div class="card metric"><div class="label">Fiber Cables</div><div class="value">${x.totalCables||0}</div></div><div class="card metric"><div class="label">Total Cores</div><div class="value">${x.totalCores||0}</div></div><div class="card metric"><div class="label">Used / Available</div><div class="value">${x.usedCores||0} / ${x.availableCores||0}</div></div><div class="card metric"><div class="label">Splitters</div><div class="value">${x.totalSplitters||0}</div></div><div class="card metric"><div class="label">Faulty Cores</div><div class="value red">${x.faultyCores||0}</div></div><div class="card metric"><div class="label">Splitter Ports</div><div class="value">${x.usedPorts||0} / ${x.availablePorts||0}</div></div><div class="card metric"><div class="label">Power Warnings</div><div class="value amber">${x.powerWarnings||0}</div></div><div class="card metric"><div class="label">Open Faults</div><div class="value red">${x.openFaults||0}</div></div></div>`}
function fiberMappingPage(){const f=fiberState;return head('Fiber Mapping','Visual topology and route management.','<button class="btn primary" data-fm-add-route>+ Add Route</button><button class="btn" data-fm-refresh>Refresh</button>')+fiberSummaryCards()+`<div class="card section"><div class="kpi"><div><h2>Optical Topology</h2><p class="subtle">OLT → Fiber → Joint/Splice → Splitter → Drop → ONU/ONT → Customer</p></div><span class="badge neutral">${f.routes.length} routes</span></div><div class="fiber-topology" id="fiberTopology">${f.routes.length?f.routes.map(r=>{let path=[];try{path=JSON.parse(r.path_json||'[]')}catch{};path=r.path||path;return `<div class="fiber-route"><div class="fiber-route-title"><b>${esc(r.name)}</b><span class="subtle">${esc(r.branch||'')} ${r.customer_id?'• Customer '+esc(r.customer_id):''}</span></div><div class="fiber-chain">${path.length?path.map((n,i)=>`<div class="fiber-map-node"><b>${esc(n.name||n.type||n.id||'Node')}</b><div class="subtle">${esc(n.type||'')}</div>${n.loss_db!=null?`<div class="loss">${Number(n.loss_db).toFixed(2)} dB</div>`:''}</div>${i<path.length-1?'<div class="fiber-arrow">→</div>':''}`).join(''):'<span class="subtle">No mapped path elements yet.</span>'}</div><div class="actions"><button class="btn small" data-fm-budget="${esc(r.id)}">Optical Budget</button></div></div>`}).join(''):'<div class="empty">No routes yet. Create a route to build the optical path.</div>'}</div></div>`+`<div class="twocol section"><div class="card"><h2>Fiber Cables</h2><div class="tablewrap"><table class="table"><thead><tr><th>Cable</th><th>Cores</th><th>Length</th><th>From → To</th><th>Status</th></tr></thead><tbody>${f.cables.slice(0,50).map(c=>`<tr><td>${esc(c.name)}</td><td>${c.core_count}</td><td>${Number(c.length_km||0).toFixed(3)} km</td><td>${esc(c.from_location||'')} → ${esc(c.to_location||'')}</td><td>${esc(c.status)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No cables.</td></tr>'}</tbody></table></div></div><div class="card"><h2>Splitters</h2><div class="tablewrap"><table class="table"><thead><tr><th>Name</th><th>Ratio</th><th>Ports</th><th>Loss</th></tr></thead><tbody>${f.splitters.slice(0,50).map(s=>{const ports=s.ports||[];return `<tr><td>${esc(s.name)}</td><td>${esc(s.ratio)}</td><td>${ports.filter(p=>p.status==='Used').length}/${ports.length}</td><td>${Number((s.actual_loss_db ?? s.estimated_loss_db) || 0).toFixed(2)} dB</td></tr>`}).join('')||'<tr><td colspan="4" class="empty">No splitters.</td></tr>'}</tbody></table></div></div></div>`}
function fiberCablesPage(){const f=fiberState;return head('Fiber Cables','Inventory and core generation for all optical cables.','<button class="btn primary" data-fcable-add>+ Add Fiber Cable</button><button class="btn" data-fiber-refresh>Refresh</button>')+fiberSummaryCards()+`<div class="card section"><div class="tablewrap"><table class="table"><thead><tr><th>ID</th><th>Name</th><th>Type</th><th>Cores</th><th>Length</th><th>From</th><th>To</th><th>Manufacturer</th><th>Status</th><th>Action</th></tr></thead><tbody>${f.cables.map(c=>`<tr><td>${esc(c.id)}</td><td>${esc(c.name)}</td><td>${esc(c.fiber_type)}</td><td>${c.core_count}</td><td>${Number(c.length_km||0).toFixed(3)} km</td><td>${esc(c.from_location)}</td><td>${esc(c.to_location)}</td><td>${esc(c.manufacturer||'—')}</td><td>${esc(c.status)}</td><td><button class="btn small danger" data-fcable-del="${esc(c.id)}">Delete</button></td></tr>`).join('')||'<tr><td colspan="10" class="empty">No fiber cables.</td></tr>'}</tbody></table></div></div>`}
function fiberCoresPage(){const f=fiberState;let rows=[];f.cables.forEach(c=>(c.cores||[]).forEach(x=>rows.push({...x,cable_name:c.name})));return head('Fiber Cores','Track utilization, route assignment and core status.','<button class="btn" data-fiber-refresh>Refresh</button>')+fiberSummaryCards()+`<div class="card section"><div class="actions"><input class="search" id="fiberCoreSearch" placeholder="Search cable/core/customer route..."></div><div class="tablewrap"><table class="table"><thead><tr><th>Cable</th><th>Core</th><th>Status</th><th>OLT Port</th><th>Joint</th><th>Splitter</th><th>Customer Route</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.cable_name)}</td><td>Core ${String(x.core_no).padStart(2,'0')}</td><td><span class="badge ${x.status==='Fault'?'unpaid':x.status==='Active'?'paid':'partial'}">${esc(x.status)}</span></td><td>${esc(x.olt_port||'—')}</td><td>${esc(x.joint_id||'—')}</td><td>${esc(x.splitter_id||'—')}</td><td>${esc(x.customer_route||'—')}</td><td><button class="btn small" data-core-edit="${esc(x.id)}">Edit</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No cores.</td></tr>'}</tbody></table></div></div>`}
function fiberJointsPage(){const f=fiberState;return head('Joint / Splice Management','Manage joint boxes, splice connections and measured splice loss.','<button class="btn primary" data-fjoint-add>+ Add Joint</button><button class="btn" data-fsplice-add>+ Add Splice</button>')+`<div class="twocol section"><div class="card"><h2>Joint Boxes</h2><div class="tablewrap"><table class="table"><thead><tr><th>Name</th><th>Location</th><th>Branch</th><th>Status</th></tr></thead><tbody>${f.joints.map(j=>`<tr><td>${esc(j.name)}</td><td>${esc(j.location)}</td><td>${esc(j.branch)}</td><td>${esc(j.status)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No joints.</td></tr>'}</tbody></table></div></div><div class="card"><h2>Splices</h2><div class="tablewrap"><table class="table"><thead><tr><th>Joint</th><th>Core A</th><th>Core B</th><th>Loss</th></tr></thead><tbody>${f.joints.flatMap(j=>[]).length?'' : f.joints.map(j=>f.joints.length?[]:[])}${([]).length?'':''}${f._splices?.map(x=>`<tr><td>${esc(x.joint_id)}</td><td>${esc(x.core_a)}</td><td>${esc(x.core_b)}</td><td>${Number(x.loss_db||0).toFixed(2)} dB</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No splice records loaded.</td></tr>'}</tbody></table></div></div></div>`}
function fiberSplittersPage(){const f=fiberState;return head('Splitter Management','Manage splitter ratios, ports, estimated and measured insertion loss.','<button class="btn primary" data-fsplitter-add>+ Add Splitter</button>')+`<div class="card section"><div class="tablewrap"><table class="table"><thead><tr><th>Splitter</th><th>Type</th><th>Ratio</th><th>Input</th><th>Used</th><th>Available</th><th>Estimated</th><th>Actual</th><th>Ports</th></tr></thead><tbody>${f.splitters.map(s=>{const ps=s.ports||[],used=ps.filter(p=>p.status==='Used').length;return `<tr><td>${esc(s.name)}</td><td>${esc(s.type)}</td><td>${esc(s.ratio)}</td><td>${esc(s.input_core||'—')}</td><td>${used}</td><td>${Math.max(0,ps.length-used)}</td><td>${Number(s.estimated_loss_db||0).toFixed(2)} dB</td><td>${s.actual_loss_db==null?'—':Number(s.actual_loss_db).toFixed(2)+' dB'}</td><td><button class="btn small" data-splitter-ports="${esc(s.id)}">Manage Ports</button></td></tr>`}).join('')||'<tr><td colspan="9" class="empty">No splitters.</td></tr>'}</tbody></table></div></div>`}
function fiberCalculationPage(){return head('Fiber Calculation','Dynamic route-based optical loss calculation.','<button class="btn primary" data-fcalc-route>Calculate From Existing Route</button><button class="btn" data-fcalc-manual>Manual Calculation</button>')+`<div id="fiberCalcHost"><div class="card section"><div class="empty">Select an existing mapped route to automatically retrieve cable lengths, splices and splitters, or start a manual calculation.</div></div></div>`}
function fiberBudgetPage(){return head('Optical Power Budget','Compare estimated optical power with actual measured ONU/ONT RX power.','<button class="btn" data-fiber-refresh>Refresh</button>')+`<div class="card section"><div class="tablewrap"><table class="table"><thead><tr><th>Route</th><th>OLT TX</th><th>Total Loss</th><th>Estimated RX</th><th>Actual RX</th><th>Difference</th><th>ONU Min</th><th>ONU Max</th><th>Status</th></tr></thead><tbody>${fiberState.calculations.map(c=>{const diff=c.actual_rx_dbm==null?'—':(Number(c.actual_rx_dbm)-Number(c.expected_rx_dbm)).toFixed(2)+' dB';return `<tr><td>${esc(c.name||c.route_id||'—')}</td><td>${Number(c.olt_tx_dbm||0).toFixed(2)} dBm</td><td>${Number(c.total_loss_db||0).toFixed(2)} dB</td><td>${Number(c.expected_rx_dbm||0).toFixed(2)} dBm</td><td>${c.actual_rx_dbm==null?'—':Number(c.actual_rx_dbm).toFixed(2)+' dBm'}</td><td>${diff}</td><td>${c.onu_min_rx_dbm==null?'—':c.onu_min_rx_dbm}</td><td>${c.onu_max_rx_dbm==null?'—':c.onu_max_rx_dbm}</td><td><span class="badge ${c.status==='pass'?'paid':c.status==='warning'?'partial':'unpaid'}">${esc(c.status)}</span></td></tr>`}).join('')||'<tr><td colspan="9" class="empty">No optical calculations saved.</td></tr>'}</tbody></table></div><div class="notice section">Estimated Loss and Estimated RX are calculations. Actual RX is measured telemetry/manual data only.</div></div>`}
function fiberFaultsPage(){const f=fiberState;return head('Fiber Faults','Record, track and resolve fiber faults and customer impact.','<button class="btn primary" data-ffault-add>+ Report Fault</button><button class="btn" data-fiber-refresh>Refresh</button>')+`<div class="card section"><div class="tablewrap"><table class="table"><thead><tr><th>Date</th><th>Cable</th><th>Core</th><th>Location</th><th>Type</th><th>Technician</th><th>Status</th><th>Description</th></tr></thead><tbody>${f.faults.map(x=>`<tr><td>${esc(x.fault_date)}</td><td>${esc(x.cable_id||'—')}</td><td>${esc(x.core_id||'—')}</td><td>${esc(x.location)}</td><td>${esc(x.fault_type)}</td><td>${esc(x.technician)}</td><td>${esc(x.status)}</td><td>${esc(x.description||'')}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No faults recorded.</td></tr>'}</tbody></table></div></div>`}
function fiberReportsPage(){return head('Fiber Reports','Inventory, utilization, optical power and fault reporting.','<button class="btn" data-freport="inventory">Inventory</button><button class="btn" data-freport="cores">Core Utilization</button><button class="btn" data-freport="splitters">Splitters</button><button class="btn" data-freport="faults">Faults</button><button class="btn" data-freport="power">Optical Power</button>')+`<div class="card section"><div class="notice">Reports are generated from the Fiber Management database. Use CSV export for spreadsheet workflows and browser Print → Save as PDF for PDF reports.</div><div id="fiberReportOut" class="section"><div class="empty">Choose a report above.</div></div></div>`}
function page(v){if(v==='publicPayment')return publicPaymentPage(); if(v==='monitoring')return monitoringPage(); if(v==='networkmonitor')return networkMonitoringPage(); if(v==='oltadapter')return oltAdapterPage(); if(v==='pingmonitor')return pingMonitoringPage(); if(v==='fiberMapping')return fiberMappingPage(); if(v==='fiberCables')return fiberCablesPage(); if(v==='fiberCores')return fiberCoresPage(); if(v==='fiberJoints')return fiberJointsPage(); if(v==='fiberSplitters')return fiberSplittersPage(); if(v==='fiberCalculation')return fiberCalculationPage(); if(v==='fiberBudget')return fiberBudgetPage(); if(v==='fiberFaults')return fiberFaultsPage(); if(v==='fiberReports')return fiberReportsPage(); if(!can(v))return head('Access Restricted','Your staff account does not have permission to view this section.')+'<div class="card"><div class="empty">Ask an administrator to grant the required permission.</div></div></div>';switch(v){case'companies':return companiesPage();case'customers':return customersPage();case'customerDetail':return customerDetailPage(viewCustomerId);case'packages':return packagesPage();case'billing':return billingPage();case'payments':return paymentsPage();case'expenses':return expensesPage();case'staff':return staffPage();case'reports':return reportsPage();case'import':return importPage();case'devices':return deviceManagementPage();case'mikrotik':return mikrotikPage();case'communications':return communicationsPage();case'integrations':return integrationsPage();case'backups':return backupsPage();case'audit':return auditPage();case'settings':return settingsPage();default:return dashboardPage()}}
function page(v){if(v==='publicPayment')return publicPaymentPage(); if(v==='monitoring')return monitoringPage(); if(v==='networkmonitor')return networkMonitoringPage(); if(v==='oltadapter')return oltAdapterPage(); if(v==='pingmonitor')return pingMonitoringPage(); if(v==='fiberMapping')return fiberMappingPage(); if(v==='fiberCalculation')return fiberCalculationPage(); if(!can(v))return head('Access Restricted','Your staff account does not have permission to view this section.')+'<div class="card"><div class="empty">Ask an administrator to grant the required permission.</div></div></div>';switch(v){case'companies':return companiesPage();case'customers':return customersPage();case'customerDetail':return customerDetailPage(viewCustomerId);case'packages':return packagesPage();case'billing':return billingPage();case'payments':return paymentsPage();case'expenses':return expensesPage();case'staff':return staffPage();case'reports':return reportsPage();case'import':return importPage();case'devices':return deviceManagementPage();case'mikrotik':return mikrotikPage();case'communications':return communicationsPage();case'integrations':return integrationsPage();case'backups':return backupsPage();case'audit':return auditPage();case'settings':return settingsPage();default:return dashboardPage()}}
function head(title,desc,buttons=''){return `<div class="page"><div class="title"><div><div class="actions" style="margin-bottom:10px"><button type="button" class="btn small" data-back>← Back</button><button type="button" class="btn small" data-home>⌂ Dashboard</button></div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${buttons}</div></div>`}
function nfBytes(v){
  if(v==null)return 0;
  if(typeof v==='number')return v;
  const s=String(v).trim().toUpperCase().replace(/,/g,'');
  const m=s.match(/^([0-9.]+)\s*(B|KB|MB|GB|TB)?$/); if(!m)return Number(s)||0;
  const n=Number(m[1]); const u=m[2]||'B'; const mul={B:1,KB:1024,MB:1024**2,GB:1024**3,TB:1024**4}; return n*(mul[u]||1);
}
function nfMbps(bytesPerSec){return Math.max(0,Number(bytesPerSec||0)*8/1e6)}
function nfPushSample(store,key,rx,tx,limit=36){store[key]=store[key]||[];store[key].push({t:new Date(),rx:Number(rx||0),tx:Number(tx||0)});if(store[key].length>limit)store[key].splice(0,store[key].length-limit);return store[key]}
function nfRateFromCounters(store,key,rxCounter,txCounter){
  const now=Date.now(), prev=store[key]; store[key]={t:now,rx:rxCounter,tx:txCounter};
  if(!prev||!prev.t)return {rx:0,tx:0}; const dt=Math.max(.25,(now-prev.t)/1000);
  const delta=(cur,old)=>{let d=Number(cur||0)-Number(old||0);if(d<0)d+=2**32;return d/dt};
  return {rx:delta(rxCounter,prev.rx),tx:delta(txCounter,prev.tx)};
}
window.__nfBw={olt:{},mt:{},counter:{},charts:{}};window.__nfPollTimer=null;
function nfDestroyChart(id){const c=window.__nfBw.charts[id];if(c&&c.getContext){c.width=1;c.height=1}delete window.__nfBw.charts[id]}
function nfCanvasSetup(id){const e=document.getElementById(id);if(!e)return null;const r=e.getBoundingClientRect();const d=Math.max(1,window.devicePixelRatio||1);e.width=Math.max(320,Math.floor(r.width*d));e.height=Math.max(220,Math.floor(r.height*d));const c=e.getContext('2d');c.setTransform(d,0,0,d,0,0);c.clearRect(0,0,r.width,r.height);return {e,c,w:r.width,h:r.height}}
function nfLineChart(id,labels,datasets){
  const q=nfCanvasSetup(id); if(!q)return; const {c,w,h}=q; window.__nfBw.charts[id]=q;
  const pad={l:58,r:18,t:30,b:34},pw=Math.max(20,w-pad.l-pad.r),ph=Math.max(20,h-pad.t-pad.b);
  const vals=datasets.flatMap(d=>d.data.map(Number)).filter(Number.isFinite); let max=Math.max(.1,...vals);
  max=max<=1?Math.max(1,Math.ceil(max*10)/10):Math.ceil(max*1.18);
  c.font='12px Inter,system-ui,sans-serif'; c.lineCap='round'; c.lineJoin='round';
  c.strokeStyle='rgba(145,160,184,.10)'; c.fillStyle='#91a0b8'; c.lineWidth=1;
  for(let i=0;i<=4;i++){const y=pad.t+ph*i/4;c.beginPath();c.moveTo(pad.l,y);c.lineTo(pad.l+pw,y);c.stroke();const v=max*(1-i/4);c.fillText(v.toFixed(v<10?1:0)+' Mbps',6,y+4)}
  c.beginPath();c.moveTo(pad.l,pad.t);c.lineTo(pad.l,pad.t+ph);c.lineTo(pad.l+pw,pad.t+ph);c.stroke();
  labels.forEach((x,i)=>{if(i===0||i===labels.length-1||i%Math.max(1,Math.ceil(labels.length/6))===0)c.fillText(x,pad.l+pw*(labels.length<=1?0:i/(labels.length-1))-18,h-10)});
  datasets.forEach((ds,di)=>{
    const color=di?'#3b9cff':'#18c98b', points=ds.data.map((v,i)=>({x:pad.l+pw*(ds.data.length<=1?0:i/(ds.data.length-1)),y:pad.t+ph*(1-Math.max(0,Number(v)||0)/max)}));
    if(!points.length)return;
    const grad=c.createLinearGradient(0,pad.t,0,pad.t+ph);grad.addColorStop(0,di?'rgba(59,156,255,.22)':'rgba(24,201,139,.22)');grad.addColorStop(1,'rgba(0,0,0,0)');
    c.beginPath(); c.moveTo(points[0].x,pad.t+ph); c.lineTo(points[0].x,points[0].y);
    for(let i=1;i<points.length;i++){const p0=points[i-1],p1=points[i],mx=(p0.x+p1.x)/2;c.quadraticCurveTo(p0.x,p0.y,mx,(p0.y+p1.y)/2);c.quadraticCurveTo(p1.x,p1.y,p1.x,p1.y)}
    c.lineTo(points[points.length-1].x,pad.t+ph);c.closePath();c.fillStyle=grad;c.fill();
    c.beginPath();c.moveTo(points[0].x,points[0].y);for(let i=1;i<points.length;i++){const p0=points[i-1],p1=points[i],mx=(p0.x+p1.x)/2;c.quadraticCurveTo(p0.x,p0.y,mx,(p0.y+p1.y)/2);c.quadraticCurveTo(p1.x,p1.y,p1.x,p1.y)}
    c.strokeStyle=color;c.lineWidth=2.6;c.shadowColor=color;c.shadowBlur=7;c.stroke();c.shadowBlur=0;
    const last=points[points.length-1];c.fillStyle=color;c.beginPath();c.arc(last.x,last.y,3.5,0,Math.PI*2);c.fill();
  });
  let lx=pad.l;datasets.forEach((ds,di)=>{c.fillStyle=di?'#3b9cff':'#18c98b';c.fillRect(lx,pad.t-14,20,3);c.fillStyle='#cbd5e4';c.fillText(ds.label,lx+27,pad.t-10);lx+=78});
}
function nfBarChart(id,labels,data){const q=nfCanvasSetup(id);if(!q)return;const {c,w,h}=q;window.__nfBw.charts[id]=q;const pad={l:52,r:18,t:28,b:46};const pw=Math.max(20,w-pad.l-pad.r),ph=Math.max(20,h-pad.t-pad.b);const vals=data.map(Number).filter(Number.isFinite);const max=Math.max(1,...vals)*1.2; c.font='12px Inter,system-ui,sans-serif';c.fillStyle='#91a0b8';c.strokeStyle='rgba(145,160,184,.12)';for(let i=0;i<=4;i++){const y=pad.t+ph*i/4;c.beginPath();c.moveTo(pad.l,y);c.lineTo(pad.l+pw,y);c.stroke();c.fillText((max*(1-i/4)).toFixed(max<10?1:0)+' Mbps',6,y+4)};const n=Math.max(1,data.length),gap=Math.min(12,pw/n*.18),bw=Math.max(10,(pw-gap*(n+1))/n);data.forEach((v,i)=>{const x=pad.l+gap+i*(bw+gap),bh=ph*(Math.max(0,Number(v)||0)/max);c.fillStyle='#7c3cff';c.fillRect(x,pad.t+ph-bh,bw,bh);c.fillStyle='#cbd5e4';const label=String(labels[i]||'').slice(0,14);c.save();c.translate(x+bw/2,h-12);c.rotate(-Math.min(.6,label.length*.035));c.textAlign='center';c.fillText(label,0,0);c.restore()});}
function renderOltBandwidthGraphs(results){results.forEach(o=>{const l=o.live||{},bw=l.bandwidth||{},ports=Array.isArray(l.ports)?l.ports:[];const rx=Number(bw.rxBps||0),tx=Number(bw.txBps||0);const sample=nfPushSample(window.__nfBw.olt,o.id,rx,tx);const labels=sample.map(x=>x.t.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'}));nfLineChart('olt-total-'+o.id,labels,[{label:'RX',data:sample.map(x=>nfMbps(x.rx))},{label:'TX',data:sample.map(x=>nfMbps(x.tx))}]);nfBarChart('olt-ports-'+o.id,ports.map(p=>p.name||('PON '+p.port)),ports.map(p=>Number(p.bandwidthMbps||0)));});}
function renderMikrotikBandwidthGraph(items){const rows=Array.isArray(items)?items:[],rates=[];rows.forEach(r=>{const key=r['.id']||r.id||r.name;const rx=nfBytes(r['rx-byte']),tx=nfBytes(r['tx-byte']);const rate=nfRateFromCounters(window.__nfBw.counter,'mt:'+key,rx,tx);rates.push({name:r.name||key,rx:rate.rx,tx:rate.tx});});const totalRx=rates.reduce((a,x)=>a+x.rx,0),totalTx=rates.reduce((a,x)=>a+x.tx,0);const sample=nfPushSample(window.__nfBw.mt,'total',totalRx,totalTx);const labels=sample.map(x=>x.t.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'}));nfLineChart('mt-total-bandwidth',labels,[{label:'RX',data:sample.map(x=>nfMbps(x.rx))},{label:'TX',data:sample.map(x=>nfMbps(x.tx))}]);nfBarChart('mt-interface-bandwidth',rates.map(x=>x.name),rates.map(x=>nfMbps(x.rx+x.tx)));}

async function loadDashboardNetworkLive(force=false){
  const body=document.getElementById('networkLiveBody');
  if(!body)return;
  try{
    const base=(window.NETFLOW_ADAPTER_URL||'').replace(/\/$/,'');const r=await fetch((base?base:'')+'/api/olts',{headers:{'Accept':'application/json'},cache:'no-store'});
    if(!r.ok)throw new Error('Monitoring adapter unavailable');
    const j=await r.json();
    const olts=Array.isArray(j.olts)?j.olts:[];
    if(!olts.length){body.innerHTML='<div class="telemetry-empty" style="margin-top:12px">No OLT is configured in the monitoring adapter. Open Network / OLT → OLT Dashboard and add the OLT SNMP community.</div>';return;}
    const results=await Promise.all(olts.map(async o=>{
      try{const base2=(window.NETFLOW_ADAPTER_URL||'').replace(/\/$/,'');const rr=await fetch((base2?base2:'')+'/api/olts/'+encodeURIComponent(o.id)+'/live?refresh=true',{headers:{'Accept':'application/json'},cache:'no-store'});return {...o,live:await rr.json()}}catch(e){return {...o,live:{status:'offline',error:e.message}}}}));
    body.innerHTML='<div class="grid" style="margin-top:12px">'+results.map(o=>{const l=o.live||{},st=l.status||'unknown',bw=l.bandwidth||{};return '<div class="card"><div class="kpi"><div><b>'+esc(o.name||o.id)+'</b><div class="subtle mono">'+esc(o.host||o.ip||'—')+'</div></div><span class="badge '+(st==='online'?'paid':st==='offline'?'unpaid':'neutral')+'">'+esc(st.toUpperCase())+'</span></div><div class="olt-meta"><div class="olt-stat"><span class="label">PON</span><b>'+((l.ponCount??'—'))+'</b></div><div class="olt-stat"><span class="label">ONUs Online</span><b class="green">'+((l.onuOnline??'—'))+'</b></div><div class="olt-stat"><span class="label">ONUs Offline</span><b class="red">'+((l.onuOffline??'—'))+'</b></div><div class="olt-stat"><span class="label">Total Bandwidth</span><b class="blue">'+(bw.totalMbps!=null?Number(bw.totalMbps).toFixed(2)+' Mbps':'—')+'</b></div></div><div class="chartwrap section" style="height:230px"><canvas id="olt-total-'+esc(o.id)+'"></canvas></div><div class="chartwrap section" style="height:210px"><canvas id="olt-ports-'+esc(o.id)+'"></canvas></div>'+(l.error?'<div class="notice" style="margin-top:10px">'+esc(l.error)+'</div>':'')+'</div>'}).join('')+'</div>';renderOltBandwidthGraphs(results);}catch(e){body.innerHTML='<div class="telemetry-empty" style="margin-top:12px">'+esc(e.message)+'<br><span class="tiny">Start the included adapter with adapter/start.bat, then open the dashboard through http://127.0.0.1:8080/.</span></div>';}
}

