function renderSelectedOltBandwidth(){const d=(db.devices||[]).find(x=>x.id===selectedDeviceId),l=d?.lastTelemetry||{},bw=l.bandwidth||{};if(!d)return;const sample=nfPushSample(window.__nfBw.olt,'device:'+d.id,Number(bw.rxBps||0),Number(bw.txBps||0));const labels=sample.map(x=>x.t.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'}));nfLineChart('olt-device-total',labels,[{label:'RX',data:sample.map(x=>nfMbps(x.rx))},{label:'TX',data:sample.map(x=>nfMbps(x.tx))}]);const ports=Array.isArray(l.ports)?l.ports:[];nfBarChart('olt-device-ports',ports.map(x=>x.name||('PON '+x.port)),ports.map(x=>Number(x.bandwidthMbps||0)));}
