function closeModal(){document.getElementById('modalBack').classList.remove('show')}
function closeMobile(){document.getElementById('sidebar').classList.remove('open');document.getElementById('overlay').classList.remove('show')}
function csv(rows){if(!rows.length)return '';const keys=Object.keys(rows[0]);return [keys.join(','),...rows.map(r=>keys.map(k=>'"'+String(r[k]??'').replace(/"/g,'""')+'"').join(','))].join('\n')}
function download(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/csv'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
async function adapterFetch(path,options={}){
  const base=(window.NETFLOW_ADAPTER_URL||'').replace(/\/$/,'');
  const url=(base?base:'')+path;
  const r=await fetch(url,{...options,headers:{'Accept':'application/json','Content-Type':'application/json',...(options.headers||{})},cache:'no-store'});
  if(!r.ok){let msg='HTTP '+r.status;try{const j=await r.json();msg=j.detail||j.error||msg}catch{}throw new Error(msg)}
  return r.json();
}
async function refreshDeviceTelemetry(id,silent=false){
  const d=(db.devices||[]).find(x=>x.id===id); if(!d)return;
  const adapterBase=(window.NETFLOW_ADAPTER_URL||'').replace(/\/$/,''); const url=d.adapterId?((adapterBase?adapterBase:'')+'/api/olts/'+encodeURIComponent(d.adapterId)+'/live?refresh=true'):(d.adapterUrl||d.monitoringUrl);
  if(!url){if(!silent)toast('Configure the VSOL monitoring adapter for this OLT first.');return;}
  try{
    const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),12000);
    const r=await fetch(url,{method:'GET',headers:{'Accept':'application/json'},cache:'no-store',signal:controller.signal});clearTimeout(timer);
    if(!r.ok)throw new Error('HTTP '+r.status);
    const data=await r.json();
    d.lastTelemetry={...data,status:data.status||'online',updatedAt:new Date().toISOString()};
    localStorage.setItem(KEY,JSON.stringify(db));render();if(!silent)toast('Live VSOL telemetry refreshed');
  }catch(e){
    d.lastTelemetry={...(d.lastTelemetry||{}),status:'offline',updatedAt:new Date().toISOString(),error:String(e?.message||e)};
    localStorage.setItem(KEY,JSON.stringify(db));render();if(!silent)toast('Monitoring adapter unavailable: '+String(e?.message||e));
  }
}

async function refreshMikrotikBandwidthOnly(){
  if(view!=='mikrotik')return;
  const tab=window.__mtTab||'overview'; if(tab!=='overview'&&tab!=='interfaces')return;
  try{const ir=await mtFetch('/api/mikrotik/interfaces');renderMikrotikBandwidthGraph(ir.items||[])}catch(e){}
}
async function refreshSelectedOltBandwidthOnly(){
  if(view!=='devices'||deviceTab!=='bandwidth')return;
  const d=(db.devices||[]).find(x=>x.id===selectedDeviceId); if(!d?.adapterId)return;
  try{await refreshDeviceTelemetry(d.id,true);requestAnimationFrame(renderSelectedOltBandwidth)}catch(e){}
}

function startLiveBandwidthPolling(){if(window.__nfPollTimer)clearInterval(window.__nfPollTimer);window.__nfPollTimer=setInterval(async()=>{if(view==='mikrotik'){await refreshMikrotikBandwidthOnly()}else if(view==='devices'){await refreshSelectedOltBandwidthOnly()}},1500)}

function wirePublicPayment(){const token=new URLSearchParams(location.search).get('pay');const x=paymentTokenDecode(token);const i=x?db.invoices.find(v=>v.id===x.invoiceId):null;const pay=document.getElementById('publicPayNow');if(pay)pay.onclick=()=>{if(!i)return alert('Invoice data is not available in this browser. Configure cloud/public payment storage for cross-device payments.');const u=gatewayUrlFor(i);if(!u)return alert('Payment gateway is not configured. Go to API Integrations and set Checkout URL first.');window.location.href=u};const ep=document.getElementById('publicEasyPay');if(ep)ep.onclick=()=>{const u=i?gatewayUrlForProvider(i,'easypaisa'):tokenGatewayUrl(x,'easypaisa');if(!u)return alert('EasyPaisa is not configured.');window.location.href=u};const jc=document.getElementById('publicJazzPay');if(jc)jc.onclick=()=>{const u=i?gatewayUrlForProvider(i,'jazzcash'):tokenGatewayUrl(x,'jazzcash');if(!u)return alert('JazzCash is not configured.');window.location.href=u};const demo=document.getElementById('publicDemoPay');if(demo)demo.onclick=()=>{if(!i)return alert('Invoice not found in this browser.');if(confirm('Simulate successful online payment for '+i.no+'? This does not charge money.')){markInvoicePaid(i.id,Math.max(0,Number(i.retail)-Number(i.paid||0)),'Demo Online Payment','DEMO-'+Date.now());render()}}}

function normalizePhone(v){let n=String(v||'').replace(/\D/g,'');if(n.startsWith('0'))n='92'+n.slice(1);if(!n.startsWith('92')&&n.length===10)n='92'+n;return '+'+n}
function massWhatsAppInvoices(target){const now=new Date();return db.invoices.filter(i=>{const outstanding=Number(i.retail||0)>Number(i.paid||0);if(!outstanding)return false;const c=db.customers.find(x=>x.id===i.customerId);if(!c?.phone)return false;if(target==='overdue'){const d=i.dueDate?new Date(i.dueDate+'T23:59:59'):null;return d&&!isNaN(d)&&d<now}if(target==='due3'){const d=i.dueDate?new Date(i.dueDate+'T23:59:59'):null;return d&&!isNaN(d)&&d>=now&&d<=new Date(now.getTime()+3*86400000)}return true})}
function wireExcelDirectButtons(){
 const setup=(btnId,inputId,type,template)=>{
  const b=document.getElementById(btnId),f=document.getElementById(inputId); if(!b||!f)return;
  b.onclick=()=>{f.value='';f.click()};
  f.onchange=async()=>{const file=f.files?.[0];if(!file)return;try{const rows=await readImportFile(file);const result=importRows(type,rows);save();const detail=result.errors.length?'\n\n'+result.errors.slice(0,12).join('\n'):'';alert(`${type==='companies'?'Companies':type==='packages'?'Packages':'Customers'} import complete.\nAdded: ${result.added}\nUpdated: ${result.updated}\nSkipped: ${result.skipped}${detail}`);}catch(e){alert('Excel import failed: '+e.message)}finally{f.value=''}};
  const t=document.getElementById(btnId.replace('Btn','TemplateBtn')); if(t)t.onclick=()=>download(template.name,csv(template.rows));
 };
 setup('companyExcelBtn','companyExcelFile','companies',{name:'companies-template.csv',rows:[['name','code','phone','email','notes'],['Example Internet','EX01','03001234567','info@example.com','']]});
 setup('packageExcelBtn','packageExcelFile','packages',{name:'packages-template.csv',rows:[['name','company','bandwidth','cost','retail','duration'],['10 Mbps','Example Internet','10 Mbps','500','700','30 Days']]});
 setup('customerExcelImportBtn','customerExcelFile','customers',{name:'customers-template.csv',rows:[['name','username','phone','company','package','retail','billingDay','status'],['Ali','ali01','03001234567','Example Internet','10 Mbps','700','1','Active']]});
}
