async function loadNotificationPanel(){const panel=document.getElementById('notificationPanel');if(!panel)return;try{const j=await pingApi('/api/ping-monitor/alerts');const alerts=(j.alerts||[]).filter(x=>!x.resolved_at).slice(0,20);const c=document.getElementById('notifCount');if(c){c.textContent=alerts.length;c.classList.toggle('hidden',!alerts.length)}panel.innerHTML=`<h3>Network Notifications</h3>${alerts.length?alerts.map(a=>`<div class="ping-alert ${a.severity==='warning'?'warning':''}"><b>${a.severity==='critical'?'🔴':'🟠'} ${esc(a.message)}</b><div class="subtle tiny">${pingDateTime(a.created_at)}</div></div>`).join(''):'<div class="empty">No active network alerts.</div>'}`}catch(e){panel.innerHTML='<div class="empty">Monitoring Agent Offline</div>'}}
document.getElementById('notificationBell')?.addEventListener('click',async e=>{e.stopPropagation();document.getElementById('notificationPanel')?.classList.toggle('show');if(document.getElementById('notificationPanel')?.classList.contains('show'))await loadNotificationPanel()});document.addEventListener('click',e=>{if(!e.target.closest('#notificationPanel')&&!e.target.closest('#notificationBell'))document.getElementById('notificationPanel')?.classList.remove('show')});setInterval(()=>{if(document.getElementById('notificationBell'))loadNotificationPanel()},10000);setInterval(()=>{if(view==='dashboard')loadPingDashboardSummary()},5000);

function generateMonthly(){const period=new Date().toLocaleString('en-US',{month:'long',year:'numeric'});let added=0;customers().filter(c=>c.status!=='Suspended').forEach(c=>{const exists=db.invoices.some(i=>i.customerId===c.id&&i.period===period);if(exists)return;const p=packageOf(c.packageId);db.invoices.push({id:uid(),no:'INV-'+new Date().getFullYear()+'-'+String(db.invoices.length+1).padStart(4,'0'),customerId:c.id,companyId:c.companyId,period,dueDate:today(),retail:Number(c.retail||p?.retail||0),cost:Number(p?.cost||0),paid:0});added++});save();toast(added+' monthly invoice(s) created');}

function importKey(v){return String(v??'').trim().toLowerCase().replace(/[\s_-]+/g,'').replace(/[^a-z0-9]/g,'')}
function importRow(r){const o={};Object.keys(r||{}).forEach(k=>{o[importKey(k)]=typeof r[k]==='string'?r[k].trim():r[k]});return o}
function importVal(r,names,def=''){for(const n of names){const v=r[importKey(n)];if(v!==undefined&&v!==null&&String(v).trim()!=='')return String(v).trim()}return def}
function importNum(r,names,def=0){const v=importVal(r,names,'');if(v==='')return def;const n=Number(String(v).replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:def}
function findCompanyImport(value){const q=String(value||'').trim().toLowerCase();if(!q)return null;return db.companies.find(c=>String(c.name||'').trim().toLowerCase()===q||String(c.code||'').trim().toLowerCase()===q)||db.companies.find(c=>String(c.name||'').trim().toLowerCase().includes(q)||String(c.code||'').trim().toLowerCase().includes(q))||null}
function findPackageImport(companyId,value){const q=String(value||'').trim().toLowerCase();if(!q)return null;return db.packages.find(p=>p.companyId===companyId&&String(p.name||'').trim().toLowerCase()===q)||db.packages.find(p=>p.companyId===companyId&&String(p.name||'').trim().toLowerCase().includes(q))||null}
async function readImportFile(f){return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('Could not read the selected file.'));reader.onload=e=>{try{let rows;if(/\.csv$/i.test(f.name)){const text=e.target.result;const wb=XLSX.read(text,{type:'string'});rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''});}else{const wb=XLSX.read(e.target.result,{type:'array',cellDates:false});const ws=wb.Sheets[wb.SheetNames[0]];if(!ws)throw new Error('No worksheet found.');rows=XLSX.utils.sheet_to_json(ws,{defval:'',raw:false});}resolve(rows.map(importRow).filter(r=>Object.values(r).some(v=>String(v??'').trim()!=='')));}catch(err){reject(err)}};if(/\.csv$/i.test(f.name))reader.readAsText(f);else reader.readAsArrayBuffer(f)})}
function importRows(type,rawRows){const rows=rawRows.map(importRow);const result={added:0,updated:0,skipped:0,errors:[]};
 rows.forEach((r,i)=>{try{
  if(type==='companies'){
   const name=importVal(r,['name','company','companyname','supplier','suppliername']);if(!name){result.skipped++;result.errors.push(`Row ${i+2}: company name missing`);return}
   const code=importVal(r,['code','companycode','suppliercode']);const existing=db.companies.find(c=>String(c.name||'').trim().toLowerCase()===name.toLowerCase()||(code&&String(c.code||'').trim().toLowerCase()===code.toLowerCase()));
   const data={name,code,phone:importVal(r,['phone','mobile','contact','contactnumber']),email:importVal(r,['email','emailaddress']),notes:importVal(r,['notes','note'])};
   if(existing){Object.assign(existing,data);result.updated++;}else{db.companies.push({id:uid(),...data});result.added++;}
  } else if(type==='packages'){
   const name=importVal(r,['name','package','packagename','plan','planname']);if(!name){result.skipped++;result.errors.push(`Row ${i+2}: package name missing`);return}
   const companyRef=importVal(r,['company','companyname','companycode','supplier','suppliername','suppliercode']);const c=findCompanyImport(companyRef);if(!c){result.skipped++;result.errors.push(`Row ${i+2}: company '${companyRef||'—'}' not found`);return}
   const data={companyId:c.id,name,bandwidth:importVal(r,['bandwidth','speed','packagebandwidth']),cost:importNum(r,['cost','suppliercost','rate','buyingprice','purchaseprice']),retail:importNum(r,['retail','sale','sellingprice','customerprice','price']),duration:importVal(r,['duration','validity','period'],'30 Days')};
   const existing=findPackageImport(c.id,name);if(existing){Object.assign(existing,data);result.updated++;}else{db.packages.push({id:uid(),...data});result.added++;}
  } else if(type==='customers'){
   const name=importVal(r,['name','customer','customername']);if(!name){result.skipped++;result.errors.push(`Row ${i+2}: customer name missing`);return}
   const c=findCompanyImport(importVal(r,['company','companyname','companycode','supplier']));if(!c){result.skipped++;result.errors.push(`Row ${i+2}: company not found`);return}
   const p=findPackageImport(c.id,importVal(r,['package','packagename','plan']));
   const username=importVal(r,['username','user','userid','login']);const existing=db.customers.find(x=>(username&&String(x.username||'').toLowerCase()===username.toLowerCase())||(String(x.name||'').toLowerCase()===name.toLowerCase()&&x.companyId===c.id));
   const data={name,username,phone:importVal(r,['phone','mobile','contact']),status:importVal(r,['status','state'],'Active'),companyId:c.id,packageId:p?.id||'',retail:importNum(r,['retail','sale','customerprice','price'],p?.retail||0),billingDay:Math.max(1,Math.min(31,importNum(r,['billingday','billingdate','duedate'],1)))};
   if(existing){Object.assign(existing,data);result.updated++;}else{db.customers.push({id:uid(),...data});result.added++;}
  }
 }catch(e){result.skipped++;result.errors.push(`Row ${i+2}: ${e.message}`)}});return result}

async function doImport(){
 const f=document.getElementById('importFile')?.files[0],type=document.getElementById('importType')?.value;
 if(!f)return alert('Select an Excel or CSV file first.');
 try{
  const rows=await readImportFile(f);
  const result=importRows(type,rows);
  save();
  alert(`Import completed.\nAdded: ${result.added}\nUpdated: ${result.updated}\nSkipped: ${result.skipped}${result.errors.length?'\nErrors:\n'+result.errors.slice(0,15).join('\n'):''}`);
 }catch(err){alert('Import error: '+err.message)}
}
