// V16 interaction hardening: modal cancel, Escape, backdrop, Back/Dashboard buttons and Excel paste import.
(function(){
  function closeAny(){ var b=document.getElementById('modalBack'); if(b)b.classList.remove('show'); }
  document.addEventListener('click',function(e){
    var c=e.target.closest('[data-close]'); if(c){e.preventDefault();e.stopPropagation();closeAny();return;}
    var back=e.target.closest('[data-back]'); if(back){e.preventDefault();closeMobile(); if(window.history.length>1){history.back()} else {view='dashboard';render()} return;}
    var home=e.target.closest('[data-home]'); if(home){e.preventDefault();closeAny();closeMobile();view='dashboard';render();return;}
    if(e.target.id==='modalBack'){closeAny();return;}
    var t=e.target.closest('[data-template]'); if(t){e.preventDefault();var type=t.dataset.template;var rows={companies:[['name','code','phone','email'],['Example Internet','EX01','03001234567','info@example.com']],packages:[['name','company','bandwidth','cost','retail','duration'],['10 Mbps','Example Internet','10 Mbps','500','700','30 Days']],customers:[['name','username','phone','company','package','retail','billingDay','status'],['Ali','ali01','03001234567','Example Internet','10 Mbps','700','1','Active']]};download(type+'-template.csv',csv(rows));return;}
    if(e.target.id==='doPasteImport'){e.preventDefault();pasteImport();return;}
  },true);
  document.addEventListener('keydown',function(e){if(e.key==='Escape')closeAny();if(e.altKey&&e.key==='ArrowLeft'){e.preventDefault();history.back()}});
  function pasteImport(){var ta=document.getElementById('excelPaste'),type=document.getElementById('pasteType')?.value||'companies';var text=(ta?.value||'').trim();if(!text)return alert('Excel data paste karo.');var lines=text.split(/\r?\n/).filter(Boolean);var rows=lines.map(function(line){return line.split(/\t|,(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)/).map(function(x){return x.trim().replace(/^\"|\"$/g,'')})});var h=rows.shift().map(function(x){return x.toLowerCase().trim()});var objs=rows.map(function(r){var o={};h.forEach(function(k,i){o[k]=r[i]||''});return o});
    try{if(type==='companies')objs.forEach(function(r){if(!r.name)return;db.companies.push({id:uid(),name:r.name,code:r.code||'',phone:r.phone||'',email:r.email||'',notes:r.notes||''})});
    if(type==='packages')objs.forEach(function(r){var c=db.companies.find(function(c){return c.name.toLowerCase()===String(r.company||'').toLowerCase()});if(c&&r.name)db.packages.push({id:uid(),companyId:c.id,name:r.name,bandwidth:r.bandwidth||'',cost:+(r.cost||r.rate||0),retail:+(r.retail||r.sale||0),duration:r.duration||'30 Days'})});
    if(type==='customers')objs.forEach(function(r){var c=db.companies.find(function(c){return c.name.toLowerCase()===String(r.company||'').toLowerCase()});var p=db.packages.find(function(p){return p.companyId===c?.id&&p.name.toLowerCase()===String(r.package||'').toLowerCase()});if(c&&r.name)db.customers.push({id:uid(),name:r.name,username:r.username||r.user||'',phone:r.phone||'',status:r.status||'Active',companyId:c.id,packageId:p?.id||'',retail:+(r.retail||r.sale||p?.retail||0),billingDay:+(r.billingDay||1)})});save();toast('Excel pasted data imported successfully');if(ta)ta.value='';render();}catch(err){alert('Paste import error: '+err.message)}}
})();

