async function fiberManualCalc(){const host=document.getElementById('fiberCalcHost');if(!host)return;host.innerHTML=`<div class="card section"><h2>Manual Optical Budget</h2><div class="formgrid"><div class="field"><label>OLT TX Power (dBm)</label><input id="fmTx" type="number" step="0.1" value="5"></div><div class="field"><label>Fiber Length (km)</label><input id="fmKm" type="number" step="0.001" value="1"></div><div class="field"><label>Fiber Loss (dB/km)</label><input id="fmDb" type="number" step="0.01" value="0.25"></div><div class="field"><label>Splices</label><input id="fmSp" type="number" value="0"></div><div class="field"><label>Splice Loss (dB)</label><input id="fmSpl" type="number" step="0.01" value="0.10"></div><div class="field"><label>Connectors</label><input id="fmCo" type="number" value="2"></div><div class="field"><label>Connector Loss (dB)</label><input id="fmCol" type="number" step="0.01" value="0.30"></div><div class="field"><label>Splitter Loss (dB)</label><input id="fmSplt" type="number" step="0.01" value="10.5"></div><div class="field"><label>Other Loss (dB)</label><input id="fmOther" type="number" step="0.01" value="0"></div><div class="field"><label>Safety Margin (dB)</label><input id="fmMargin" type="number" step="0.1" value="3"></div><div class="field"><label>ONU Minimum RX (dBm)</label><input id="fmMin" type="number" step="0.1"></div><div class="field"><label>ONU Maximum RX (dBm)</label><input id="fmMax" type="number" step="0.1"></div><div class="field"><label>Actual RX (dBm, optional)</label><input id="fmActual" type="number" step="0.1"></div></div><div class="section fiber-formula" id="fmResult"></div><div class="modalfoot"><button class="btn primary" id="fmSave">Save Calculation</button></div></div>`;const calc=()=>{const g=id=>Number(document.getElementById(id)?.value||0);const fiber=g('fmKm')*g('fmDb'),splice=g('fmSp')*g('fmSpl'),conn=g('fmCo')*g('fmCol'),split=g('fmSplt'),other=g('fmOther'),margin=g('fmMargin'),total=fiber+splice+conn+split+other+margin,rx=g('fmTx')-total,act=document.getElementById('fmActual').value===''?null:g('fmActual');document.getElementById('fmResult').innerHTML=`Fiber Loss: ${fiber.toFixed(2)} dB\nSplitter Loss: ${split.toFixed(2)} dB\nSplice Loss: ${splice.toFixed(2)} dB\nConnector Loss: ${conn.toFixed(2)} dB\nOther Loss: ${other.toFixed(2)} dB\nSafety Margin: ${margin.toFixed(2)} dB\nTOTAL LOSS: ${total.toFixed(2)} dB\nOLT TX: ${g('fmTx').toFixed(2)} dBm\nEXPECTED ONU RX: ${rx.toFixed(2)} dBm${act==null?'':'\nACTUAL ONU RX: '+act.toFixed(2)+' dBm\nDIFFERENCE: '+(act-rx).toFixed(2)+' dB'}`;return {fiber,splice,conn,split,other,margin,total,rx,act,g}};document.querySelectorAll('#fiberCalcHost input').forEach(i=>i.addEventListener('input',calc));document.getElementById('fmSave').onclick=async()=>{const x=calc();try{await fiberApi('/api/fiber/calculations',{method:'POST',body:JSON.stringify({name:'Manual Calculation',olt_tx_dbm:x.g('fmTx'),fiber_length_km:x.g('fmKm'),fiber_loss_db_km:x.g('fmDb'),splice_count:x.g('fmSp'),splice_loss_db:x.g('fmSpl'),connector_count:x.g('fmCo'),connector_loss_db:x.g('fmCol'),splitter_loss_db:x.split,other_loss_db:x.other,safety_margin_db:x.margin,onu_min_rx_dbm:document.getElementById('fmMin').value===''?null:x.g('fmMin'),onu_max_rx_dbm:document.getElementById('fmMax').value===''?null:x.g('fmMax'),actual_rx_dbm:x.act})});toast('Calculation saved');await loadFiberState();}catch(e){toast(e.message)}};calc()}
